		// Token: 0x04000180 RID: 384
		internal const string QS_STUDENTS_RECEIVING_NOTES = "SELECT\tr.serviceproviderrequestid,r.ServiceProviderId,r.serviceproviderlucourseid,\r\n\t\tr.personid,p.lastName,p.firstName,p.middleName,p.student_no,\r\n\t\t\r\n\t\tr.lucourseid,luc.startdate,luc.enddate,luc.duration,luc.[term],luc.[subjectid],luc.course,luc.[section],\r\n\t\tluc.timeofday,luc.campus,lucd.altLookupString AS [subject],luc.department,luc.[location],luc.coursenote,\r\n\r\n\t\tr.serviceproviderlucourseid,luc2.LUCourseID AS sp_lucourseid,luc2.startdate AS sp_startdate,luc2.enddate AS sp_enddate,luc2.duration AS sp_duration,luc2.[term] AS sp_term,\t\r\n\t\tluc2.[subjectid] AS sp_subjectid,luc2.course AS sp_course,luc2.[section] AS sp_section,\r\n\t\tluc2.timeofday AS sp_timeofday,luc2.campus AS sp_campus,lucd2.altLookupString AS sp_subject,luc2.department AS sp_department,\r\n\t\tluc2.[location] AS sp_location,luc2.coursenote AS sp_coursenote\r\nFROM\tServiceProviderRequests r LEFT JOIN people p ON p.PersonID=r.personid\r\n\t\tLEFT JOIN lucourses luc ON luc.LUCourseID=r.lucourseid\r\n\t\tLEFT JOIN lucoursedata lucd ON lucd.luCourseDataID=luc.SubjectID\r\n\t\tLEFT JOIN lucourses luc2 ON luc2.LUCourseID=r.serviceproviderlucourseid\r\n\t\tLEFT JOIN lucoursedata lucd2 ON lucd2.luCourseDataID=luc2.SubjectID \r\nWHERE\tr.IsActive=1 AND r.serviceprovidertype=@sptype\r\n\t\tAND NOT r.ServiceProviderId IS NULL AND r.ServiceProviderId=@spid \r\n\t\tAND r.serviceproviderlucourseid=@lucid";

		// Token: 0x04000181 RID: 385
		internal const string QS_NOTETAKER_COURSES_BY_DATE = "SELECT\tDISTINCT spac.lucourseid INTO #t1\r\nFROM\tserviceproviderapplications spa LEFT JOIN serviceproviderapplicationcourses spac ON spac.ServiceProviderApplicationId=spa.ServiceProviderApplicationId\r\n\t\tLEFT JOIN lucourses luc ON luc.LUCourseID=spac.lucourseid\r\nWHERE\tspa.serviceproviderid=@spid AND spa.serviceprovidertype=128 AND (spac.registrationstatus IS NULL OR NOT spac.registrationstatus=2)\r\n        AND NOT ( ( luc.enddate<@sd ) OR (luc.startdate > @ed ) )\r\n\r\nSELECT\t#t1.lucourseid,luc.startdate,luc.enddate,luc.duration,luc.term,lucd.altlookupstring AS [subject],luc.course,\r\n\t\tluc.section,luc.timeofday,luc.campus,luc.subjectid\r\nFROM\t#t1 LEFT JOIN lucourses luc ON luc.lucourseid=#t1.lucourseid\r\n\t\tLEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n\r\nDROP TABLE #t1";

		// Token: 0x04000182 RID: 386
		internal const string QS_NOTETAKER_AVAILABLE_COURSE_UNIQUE_DATES = "SELECT\tDISTINCT spac.lucourseid INTO #t1\r\nFROM\tserviceproviderapplications spa LEFT JOIN serviceproviderapplicationcourses spac ON spac.ServiceProviderApplicationId=spa.ServiceProviderApplicationId\r\nWHERE\tspa.serviceproviderid=@spid AND spa.serviceprovidertype=128 AND (spac.registrationstatus IS NULL OR NOT spac.registrationstatus=2)\r\n\r\nSELECT DISTINCT x.startdate FROM\r\n(\r\nSELECT luc.startdate FROM #t1 LEFT JOIN lucourses luc ON luc.LUCourseID=#t1.lucourseid\r\nUNION\r\nSELECT luc.enddate AS startdate FROM #t1 LEFT JOIN lucourses luc ON luc.LUCourseID=#t1.lucourseid\r\n) x\r\n\r\nDROP TABLE #t1";

		// Token: 0x04000183 RID: 387
		internal const string QS_STUDENT_DOWNLOAD_HISTORY_BY_STUDENT_AND_COURSE_LAST_DATE_DOWNLOADED_FOR_EACH_LECTURE_NOTE = "SELECT nds.personid,nds.lucourseid,nds.notetakerdocumentid,nds.datedownloaded,\r\n         p.firstname,p.middlename,p.lastname,p.student_no,\r\n         luc.startdate,luc.enddate,luc.duration,luc.term,luc.subjectid,lucd.altlookupstring AS subject,luc.course,luc.[section],luc.timeofday,\r\n         nds.docname,nds.sizeinbytes,nds.datecreated,nds.notetakerid,nds.notetakerid AS serviceproviderid,nds.notes,nds.lecturedate,nds.issamplenotes,nds.deletiondate,\r\n         sp.firstname,sp.lastname,sp.student_no,sp.altid,sp.email,sp.phone1,sp.phone2\r\nFROM     NotetakingStudentDownloadHistoryMaxDatePerLectureNote nds LEFT JOIN people p ON p.personid=nds.personid\r\n         LEFT JOIN lucourses luc ON luc.lucourseid=nds.lucourseid\r\n         LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n         LEFT JOIN serviceproviders sp ON sp.serviceproviderid=nds.notetakerid\r\nWHERE    nds.personid=@pid AND nds.lucourseid=@lucid\r\nORDER BY nds.lecturedate DESC";

		// Token: 0x04000184 RID: 388
		internal const string QS_STUDENT_DOWNLOAD_HISTORY_BY_STUDENT_AND_COURSE = "SELECT nds.personid,nds.lucourseid,nds.notetakerdocumentid,nds.datedownloaded,\r\n         p.firstname,p.middlename,p.lastname,p.student_no,\r\n         luc.startdate,luc.enddate,luc.duration,luc.term,luc.subjectid,lucd.altlookupstring AS subject,luc.course,luc.[section],luc.timeofday,\r\n         nd.docname,nd.sizeinbytes,nd.datecreated,nd.notetakerid,nd.notetakerid AS serviceproviderid,nd.notes,nd.lecturedate,nd.issamplenotes,nd.deletiondate,\r\n         sp.firstname,sp.lastname,sp.student_no,sp.altid,sp.email,sp.phone1,sp.phone2\r\nFROM     NotetakerDocumentStudentDownloads nds LEFT JOIN people p ON p.personid=nds.personid\r\n         LEFT JOIN lucourses luc ON luc.lucourseid=nds.lucourseid\r\n         LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n         LEFT JOIN notetakerdocument nd ON nd.notetakerdocumentid=nds.notetakerdocumentid\r\n         LEFT JOIN serviceproviders sp ON sp.serviceproviderid=nd.notetakerid\r\nWHERE    nds.personid=@pid AND nds.lucourseid=@lucid\r\nORDER BY nds.datedownloaded DESC";

		// Token: 0x04000185 RID: 389
		internal const string QS_LOAD_NOTETAKERBASE_WITH_NOTES_AND_COURSEBASE_FOR_EQUIVALENT_COURSES = "SELECT DISTINCT ec.lucourseid,nd.notetakerid AS serviceproviderid,\r\n\tsp.firstname,sp.lastname,sp.middlename,sp.student_no,sp.email,sp.altid,\r\n    luc.startdate,luc.enddate,luc.duration,luc.term,lucd.altlookupstring AS subject,luc.course,\r\n    luc.section,luc.timeofday,lucd2.altlookupstring AS pinstructorname,luc.instructorid AS pinstructorid,\r\n    lucd2.email AS pinstructoremail,lucd2.phone AS pinstructorphone,lucd2.externalid AS pinstructorexternalid,\r\n    lucd2.id AS pinstructoremployeeid,\r\n    luc.subjectid\r\nFROM EquivalentCoursesChooser(@lucid,@equivalentsettingnum) ec LEFT JOIN NotetakerDocument nd \r\n\t\tON nd.LUCourseId=ec.lucourseid\r\nLEFT JOIN ServiceProviders sp ON sp.ServiceProviderId=nd.NotetakerID\r\nLEFT JOIN lucourses luc ON luc.lucourseid=ec.lucourseid\r\nLEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\nLEFT JOIN lucoursedata lucd2 ON lucd2.lucoursedataid=luc.notetakerid";

