		// Token: 0x0400018A RID: 394
		internal const string QS_LOOKUP_COURSE_BASE_EQUIVALENTS = "SELECT    ec.lucourseid,\r\n            luc.startdate,luc.enddate,luc.duration,luc.term,lucd.altlookupstring AS subject,luc.course,\r\n            luc.section,luc.timeofday,lucd2.altlookupstring AS pinstructorname,luc.instructorid AS pinstructorid,\r\n            lucd2.email AS pinstructoremail,lucd2.phone AS pinstructorphone,lucd2.externalid AS pinstructorexternalid,\r\n            lucd2.id AS pinstructoremployeeid,\r\n            luc.subjectid\r\nFROM        EquivalentCoursesChooser(@lucid,@equivalentsettingnum) ec LEFT JOIN lucourses luc ON luc.lucourseid=ec.lucourseid\r\n            LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n            LEFT JOIN lucoursedata lucd2 ON lucd2.lucoursedataid=luc.notetakerid";

		// Token: 0x0400018B RID: 395
		internal const string QS_NOTETAKERBASE_BY_NOTEAKEE_AND_COURSE = "SELECT    spr.serviceproviderid,sp.firstname,sp.middlename,sp.lastname,sp.student_no,\r\n            sp.email,sp.altid\r\nFROM        serviceproviderrequests spr LEFT JOIN serviceproviders sp ON sp.serviceproviderid=spr.serviceproviderid\r\nWHERE       spr.isactive=1 AND spr.personid=@pid AND spr.lucourseid=@lucid";

		// Token: 0x0400018C RID: 396
		internal const string QS_LECTURE_NOTE_DESCRIPTIONS_BY_NOTETAKER_AND_COURSE = "SELECT    nd.notetakerdocumentid,nd.docname,nd.numpages,nd.sizeinbytes,nd.datecreated,nd.DeletionDate,\r\n            nd.notetakerid AS serviceproviderid,sp.firstname,sp.middlename,sp.lastname,sp.student_no,\r\n            sp.altid,sp.email,\r\n            nd.notes,nd.lecturedate,nd.lucourseid,\r\n            luc.startdate,luc.enddate,luc.duration,luc.term,lucd.altlookupstring AS subject,luc.course,\r\n            luc.section,luc.timeofday,lucd2.altlookupstring AS pinstructorname,luc.instructorid AS pinstructorid,\r\n            lucd2.email AS pinstructoremail,lucd2.phone AS pinstructorphone,lucd2.externalid AS pinstructorexternalid,\r\n            lucd2.id AS pinstructoremployeeid,\r\n            luc.subjectid\r\nFROM        notetakerdocument nd LEFT JOIN serviceproviders sp ON sp.serviceproviderid=nd.notetakerid\r\n            LEFT JOIN lucourses luc ON luc.lucourseid=nd.lucourseid\r\n            LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n            LEFT JOIN lucoursedata lucd2 ON lucd2.lucoursedataid=luc.instructorid\r\nWHERE       nd.notetakerid=@spid AND nd.lucourseid=@lucid\r\nORDER BY    nd.lecturedate";

		// Token: 0x0400018D RID: 397
		internal const string QS_LECTURE_NOTE_DESCRIPTIONS_BY_STUDENT_AND_COURSE = "SELECT DISTINCT serviceproviderid,serviceproviderlucourseid INTO #t1 FROM ServiceProviderRequests WHERE personid=@studentpid AND NOT lucourseid IS NULL AND lucourseid=@studentlucid AND NOT serviceproviderid IS NULL AND NOT serviceproviderlucourseid IS NULL\r\n\r\nSELECT lucourseid INTO #tlucids FROM EquivalentCourses(@studentlucid)\r\n\r\n--add in possible other serviceproviders with notes\r\nINSERT INTO #t1 (serviceproviderid,serviceproviderlucourseid)\r\n\tSELECT DISTINCT notetakerid AS serviceproviderid,LUCourseId AS serviceproviderlucourseid FROM NotetakerDocument WHERE lucourseid IN (SELECT lucourseid FROM #tlucids)\r\n\r\nSELECT    nd.notetakerdocumentid,nd.docname,nd.numpages,nd.sizeinbytes,nd.datecreated,nd.DeletionDate,\r\n            nd.notetakerid AS serviceproviderid,sp.firstname,sp.middlename,sp.lastname,sp.student_no,\r\n            sp.altid,sp.email,\r\n            nd.notes,nd.lecturedate,nd.lucourseid,\r\n            luc.startdate,luc.enddate,luc.duration,luc.term,lucd.altlookupstring AS subject,luc.course,\r\n            luc.section,luc.timeofday,lucd2.altlookupstring AS pinstructorname,luc.instructorid AS pinstructorid,\r\n            lucd2.email AS pinstructoremail,lucd2.phone AS pinstructorphone,lucd2.externalid AS pinstructorexternalid,\r\n            lucd2.id AS pinstructoremployeeid,\r\n            luc.subjectid\r\nFROM        notetakerdocument nd LEFT JOIN serviceproviders sp ON sp.serviceproviderid=nd.notetakerid\r\n            LEFT JOIN lucourses luc ON luc.lucourseid=nd.lucourseid\r\n            LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n            LEFT JOIN lucoursedata lucd2 ON lucd2.lucoursedataid=luc.instructorid\r\nWHERE       EXISTS(SELECT serviceproviderid FROM #t1 WHERE serviceproviderid=nd.NotetakerID AND serviceproviderlucourseid=nd.lucourseid)\r\nORDER BY    nd.lecturedate\r\n\r\nDROP TABLE #t1\r\nDROP TABLE #tlucids";

		// Token: 0x0400018E RID: 398
		internal const string QS_LECTURE_NOTE_BY_ID = "SELECT    nd.notetakerdocumentid,nd.docname,nd.numpages,nd.sizeinbytes,nd.datecreated,nd.DeletionDate,\r\n            nd.notetakerid AS serviceproviderid,sp.firstname,sp.middlename,sp.lastname,sp.student_no,\r\n            sp.altid,sp.email,nd.binarydata,\r\n            nd.notes,nd.lecturedate,nd.lucourseid,\r\n            luc.startdate,luc.enddate,luc.duration,luc.term,lucd.altlookupstring AS subject,luc.course,\r\n            luc.section,luc.timeofday,lucd2.altlookupstring AS pinstructorname,luc.instructorid AS pinstructorid,\r\n            lucd2.email AS pinstructoremail,lucd2.phone AS pinstructorphone,lucd2.externalid AS pinstructorexternalid,\r\n            lucd2.id AS pinstructoremployeeid,\r\n            luc.subjectid\r\nFROM        notetakerdocument nd LEFT JOIN serviceproviders sp ON sp.serviceproviderid=nd.notetakerid\r\n            LEFT JOIN lucourses luc ON luc.lucourseid=nd.lucourseid\r\n            LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n            LEFT JOIN lucoursedata lucd2 ON lucd2.lucoursedataid=luc.instructorid\r\nWHERE       nd.notetakerdocumentid=@id";

		// Token: 0x0400018F RID: 399
		internal const string QU_CANCEL_NOTETAKER_ASSIGNMENT = "SELECT    ServiceProviderRequestID,personid,lucourseid,datetimerequesttitle,startdatetimerequest,enddatetimerequest,serviceprovidertype,\r\n            dateentered,startdate,enddate,whoentered,ServiceProviderId,ServiceProviderRequestDetailId,notes,studentrequested,\r\n            studentrequestedcancelnote,DateAssigned,SpecialInstructions,partsgroupid,partsdescription,serviceproviderlucourseid,\r\n            CAST(0 AS bit) AS stillactive \r\nINTO #t1\r\nFROM        serviceproviderrequests \r\nWHERE       isactive=1 AND personid=@pid AND lucourseid=@lucid AND serviceprovidertype=128\r\n\r\nINSERT INTO serviceproviderrequestshistory \r\n    (ServiceProviderRequestID,personid,lucourseid,datetimerequesttitle,startdatetimerequest,enddatetimerequest,serviceprovidertype,\r\n    dateentered,startdate,enddate,whoentered,ServiceProviderId,ServiceProviderRequestDetailId,notes,studentrequested,studentrequestedcancelnote,\r\n    DateAssigned,SpecialInstructions,partsgroupid,partsdescription,serviceproviderlucourseid,stillactive) \r\n    SELECT  * FROM #t1\r\n\r\nUPDATE      serviceproviderrequests SET dateassigned=NULL,serviceproviderid=NULL,studentrequested=0,studentrequestedcancelnote=@note,\r\n            serviceproviderlucourseid=NULL WHERE isactive=1 AND personid=@pid AND lucourseid=@lucid AND serviceprovidertype=128\r\n\r\nSELECT  DISTINCT #t1.ServiceProviderId,sp.email,sp.firstname,sp.middlename,sp.lastname,sp.student_no,sp.altid,\r\n        #t1.serviceproviderlucourseid AS lucourseid,luc.startdate,luc.enddate,luc.duration,luc.term,luc.subjectid,lucd.altlookupstring AS subject,\r\n        luc.course,luc.[section],luc.timeofday,luc.campus,luc.department,luc.location,luc.coursenote\r\nFROM    #t1 LEFT JOIN ServiceProviders sp ON sp.ServiceProviderId=#t1.ServiceProviderId\r\n        LEFT JOIN lucourses luc ON luc.lucourseid=#t1.serviceproviderlucourseid\r\n        LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n\r\nDROP TABLE #t1";

