		internal const string QU_ASSIGN_NOTETAKER = "UPDATE serviceproviderrequests SET serviceproviderid=@spid,dateassigned=getdate(),serviceproviderlucourseid=@splucid WHERE isactive=1 AND personid=@pid AND lucourseid=@lucid AND serviceprovidertype=128\r\n\r\n--load all students getting notes from this notetaker and course now\r\nSELECT\tDISTINCT r.personid\r\nFROM\tServiceProviderRequests r \r\nWHERE\tr.IsActive=1 AND r.serviceprovidertype=128\r\n\t\tAND NOT r.ServiceProviderId IS NULL AND r.ServiceProviderId=@spid \r\n\t\tAND r.serviceproviderlucourseid=@splucid";

