		// Token: 0x04000195 RID: 405
		internal const string QI_COURSE_REGISTRATION = "IF EXISTS(SELECT ServiceProviderApplicationCourseId FROM ServiceProviderApplicationCourses WHERE lucourseid=@lucid AND ServiceProviderApplicationId IN (SELECT ServiceProviderApplicationId FROM ServiceProviderApplications WHERE ServiceProviderId=@serviceproviderid))\r\nBEGIN\r\n    UPDATE ServiceProviderApplicationCourses SET registrationstatus=NULL,exemptfromdatasync=COALESCE(@isexempt,exemptfromdatasync) WHERE lucourseid=@lucid AND ServiceProviderApplicationId IN (SELECT ServiceProviderApplicationId FROM ServiceProviderApplications WHERE ServiceProviderId=@serviceproviderid)\r\n    SELECT ServiceProviderApplicationCourseId FROM ServiceProviderApplicationCourse WHERE lucourseid=@lucid AND ServiceProviderApplicationId IN (SELECT ServiceProviderApplicationId FROM ServiceProviderApplications WHERE ServiceProviderId=@serviceproviderid))\r\nEND\r\nELSE\r\nBEGIN\r\nTODO!!!\r\n    INSERT INTO ServiceProviderApplicationCourses (personid,lucourseid,whoadded,dateadded,exemptfromdatasync) VALUES (@pid,@lucid,@whoami,getdate(),COALESCE(@isexempt,0));\r\n    SELECT CAST(SCOPE_IDENTITY() AS int) AS coursesid\r\nEND";

		// Token: 0x04000196 RID: 406
		internal const string QI_CreateOrRetrieveServiceProviderApplicationIdForCourses = "IF EXISTS(SELECT serviceproviderid FROM serviceproviderapplications WHERE serviceproviderid=@spid AND serviceprovidertype=@sptype)\r\n\tSELECT serviceproviderapplicationid FROM serviceproviderapplications WHERE serviceproviderid=@spid AND serviceprovidertype=@sptype\r\n\tELSE \r\n\tBEGIN\r\nINSERT INTO serviceproviderapplications (serviceproviderid,serviceprovidertype,note1,note2,dateentered,whoentered,ispermanent,isactive,isactivecomment) \r\nSELECT @spid,@sptype,'','',getdate(),1,NULL,1,NULL  \r\nSELECT serviceproviderapplicationid FROM serviceproviderapplications WHERE serviceproviderapplicationid=@@identity\r\nEND";

		// Token: 0x04000197 RID: 407
		internal const string QI_AddServiceProviderApplicationCourse = "IF EXISTS(SELECT serviceproviderapplicationcourseid FROM serviceproviderapplicationcourses WHERE serviceproviderapplicationid=@spa AND serviceprovidertype=@sptype AND lucourseid=@lucid)\r\nBEGIN\r\n    SELECT serviceproviderapplicationcourseid FROM serviceproviderapplicationcourses WHERE serviceproviderapplicationid=@spa AND serviceprovidertype=@sptype AND lucourseid=@lucid\r\nEND\r\nELSE\r\nBEGIN\r\n    INSERT INTO serviceproviderapplicationcourses \r\n            (serviceproviderapplicationid,serviceprovidertype,lucourseid,datecancelled) \r\n    VALUES  (@spa,@sptype,@lucid,NULL);\r\n    SELECT CAST(SCOPE_IDENTITY() AS int) AS serviceproviderapplicationcourseid\r\nEND";

		// Token: 0x04000198 RID: 408
		internal const string QI_NOTETAKER = "IF NOT EXISTS(SELECT serviceproviderid FROM ServiceProviders WHERE (NOT @altid IS NULL AND altid=@altid) OR (NOT @student_no IS NULL AND student_no=@student_no))\r\nBEGIN\r\n    INSERT INTO ServiceProviders (firstname,middlename,lastname,student_no,altid,specialization,notes1,notes2,email,phone1,phone2,phonenote,address,address2,email2,addressactive,address2active)\r\n    VALUES (@firstname,@middlename,@lastname,@student_no,@altid,@specialization,@notes1,@notes2,@email,@phone1,@phone2,@phonenote,@address,@address2,@email2,@addressactive,@address2active);\r\n    SET @serviceproviderid=(SELECT TOP 1 CAST(SCOPE_IDENTITY() AS int))\r\nEND\r\nELSE \r\n    SET @serviceproviderid=0";

